import numpy as np
from portfolio_optimized_c import portfolio_risk_c as _risk, portfolio_return_c as _return


def portfolio_risk_c(weights, cov_matrix):
    # Keep nested lists unconverted: converting an 8000x8000 list duplicates
    # the matrix and can exhaust memory. The C extension handles both paths.
    if not isinstance(weights, list) or not isinstance(cov_matrix, list):
        weights = np.asarray(weights, dtype=np.float64, order="C")
        cov_matrix = np.asarray(cov_matrix, dtype=np.float64, order="C")
    return _risk(weights, cov_matrix)


def portfolio_return_c(weights, expected_returns):
    if not isinstance(weights, list) or not isinstance(expected_returns, list):
        weights = np.asarray(weights, dtype=np.float64, order="C")
        expected_returns = np.asarray(expected_returns, dtype=np.float64, order="C")
    return _return(weights, expected_returns)

__all__ = ["portfolio_risk_c", "portfolio_return_c"]
